    <div class="mt-8 grid gap-8 md:grid-cols-2">
        @foreach (var post in posts)
        {
            <a href="@post.Url()" class="group block overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-slate-200 transition hover:shadow-md">
