                {
                    <img src="@post.FeaturedImage.GetCropUrl(width: 800, height: 450)" alt="@post.Name" class="aspect-[16/9] w-full object-cover" loading="lazy" />
                }
                <div class="p-6">
                    <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("MMMM d, yyyy")</time>
                    <h3 class="mt-2 text-xl font-semibold text-slate-900 group-hover:text-indigo-600">@post.Name</h3>
                    <p class="mt-2 text-slate-600">@post.Summary</p>
                </div>
            </a>
        }
    </div>
</section>

